"""Build the shareable offline preview using actual, unmodified staging captures.

The content deliberately distinguishes implemented features, observed tests and
unfinished progression. No account saves, credentials or owner grant data are read.
"""
from pathlib import Path
import base64
import hashlib
import html

WORKSPACE=Path(__file__).resolve().parents[5]
OUTPUT=WORKSPACE/'content-release/Kronos-242-Expanded-Preview.html'

def capture(relative,alt):
    path=WORKSPACE/relative
    data=path.read_bytes()
    assert data.startswith(b'\x89PNG\r\n\x1a\n')
    return '<!-- Actual staging capture: '+path.name+'; SHA256 '+hashlib.sha256(data).hexdigest()+' -->'+\
        '<img loading="lazy" src="data:image/png;base64,'+base64.b64encode(data).decode('ascii')+'" alt="'+html.escape(alt,quote=True)+'" width="765" height="503">'

map_image=capture('local-runtime/content242-expanded-test-03/captures/map.png','Actual staged client in the tree-lined streets of Civitas illa Fortis, wearing modern equipment.')
gear_image=capture('local-runtime/content242-expanded-test-03/captures/gear.png','Actual staged client wearing Torva equipment beside a Civitas illa Fortis building.')
shadow_image=capture('local-runtime/content242-expanded-test-04/captures/wear-shadow.png',"Actual staged client wielding Tumeken's shadow through the normal inventory action at the existing home.")
scurrius_image=capture('local-runtime/content242-expanded-test-04/captures/preview-scurrius.png','Actual staged client fighting Scurrius in the rat lair, with a visible health bar and blocked hit.')
amoxliatl_image=capture('local-runtime/content242-expanded-test-04/captures/preview-amoxliatl.png','Actual staged client fighting Amoxliatl in the icy arena, with a visible red damage hit and boss health display.')

